import ArchipelCore
import Foundation

/// Everything an agent definition needs to build the command line for one session.
public struct LaunchContext: Sendable {
    public var archipelSessionID: UUID
    /// The agent's own conversation id: generated by the app for Claude, reported back by Codex.
    public var agentSessionID: String?
    public var hookExecutableURL: URL
    public var socketURL: URL
    public var workingDirectory: URL

    public init(
        archipelSessionID: UUID,
        agentSessionID: String?,
        hookExecutableURL: URL,
        socketURL: URL,
        workingDirectory: URL
    ) {
        self.archipelSessionID = archipelSessionID
        self.agentSessionID = agentSessionID
        self.hookExecutableURL = hookExecutableURL
        self.socketURL = socketURL
        self.workingDirectory = workingDirectory
    }
}

public struct LaunchCommand: Equatable, Sendable {
    public var executable: String
    public var arguments: [String]
    public var environment: [String: String]

    public init(executable: String, arguments: [String], environment: [String: String]) {
        self.executable = executable
        self.arguments = arguments
        self.environment = environment
    }

    /// Executable and arguments as one string for a POSIX shell. The environment is not
    /// included; it is passed to the terminal separately.
    public var shellCommandLine: String {
        ([executable] + arguments).map(ShellQuoting.quote).joined(separator: " ")
    }
}

public enum ShellQuoting {
    private static let safeCharacters = CharacterSet(
        charactersIn: "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789-_./=:,+@%"
    )

    public static func quote(_ word: String) -> String {
        if !word.isEmpty, word.unicodeScalars.allSatisfy(safeCharacters.contains) {
            return word
        }
        return "'" + word.replacingOccurrences(of: "'", with: #"'\''"#) + "'"
    }
}

public struct AgentDefinition: Sendable, Identifiable {
    public let id: String
    public let displayName: String
    public let symbolName: String
    public let executableName: String
    /// True when the app must put a fresh UUID into `LaunchContext.agentSessionID` before the
    /// first launch, so the session can be resumed later without waiting for a hook.
    public let presetsAgentSessionID: Bool

    private let freshLaunch: @Sendable (LaunchContext) -> LaunchCommand
    private let resumeLaunch: (@Sendable (LaunchContext, String) -> LaunchCommand)?

    public init(
        id: String,
        displayName: String,
        symbolName: String,
        executableName: String,
        presetsAgentSessionID: Bool,
        launch: @escaping @Sendable (LaunchContext) -> LaunchCommand,
        resume: (@Sendable (LaunchContext, String) -> LaunchCommand)?
    ) {
        self.id = id
        self.displayName = displayName
        self.symbolName = symbolName
        self.executableName = executableName
        self.presetsAgentSessionID = presetsAgentSessionID
        self.freshLaunch = launch
        self.resumeLaunch = resume
    }

    public func launchCommand(for context: LaunchContext) -> LaunchCommand {
        freshLaunch(context)
    }

    /// Nil when the agent cannot resume or no agent session id is known yet; start fresh then.
    public func resumeCommand(for context: LaunchContext) -> LaunchCommand? {
        guard let resumeLaunch, let agentSessionID = context.agentSessionID else { return nil }
        return resumeLaunch(context, agentSessionID)
    }
}

extension AgentDefinition {
    public static let builtIns: [AgentDefinition] = [.claude, .codex, .shell]

    public static func builtIn(id: String) -> AgentDefinition? {
        builtIns.first { $0.id == id }
    }

    public static let claude = AgentDefinition(
        id: "claude",
        displayName: "Claude Code",
        symbolName: "claude.logo",
        executableName: "claude",
        presetsAgentSessionID: true,
        launch: { context in
            // Without a preset id Claude picks its own; the SessionStart hook reports it.
            let idArguments = context.agentSessionID.map { ["--session-id", $0] } ?? []
            return LaunchCommand(
                executable: "claude",
                arguments: idArguments + ["--settings", claudeHookSettings(hook: context.hookExecutableURL)],
                environment: hookEnvironment(context)
            )
        },
        resume: { context, agentSessionID in
            LaunchCommand(
                executable: "claude",
                arguments: [
                    "--resume", agentSessionID,
                    "--settings", claudeHookSettings(hook: context.hookExecutableURL),
                ],
                environment: hookEnvironment(context)
            )
        }
    )

    public static let codex = AgentDefinition(
        id: "codex",
        displayName: "Codex",
        symbolName: "openai.logo",
        executableName: "codex",
        presetsAgentSessionID: false,
        launch: { context in
            LaunchCommand(
                executable: "codex",
                arguments: codexOverrides(hook: context.hookExecutableURL),
                environment: hookEnvironment(context)
            )
        },
        resume: { context, agentSessionID in
            LaunchCommand(
                executable: "codex",
                arguments: ["resume"] + codexOverrides(hook: context.hookExecutableURL) + [agentSessionID],
                environment: hookEnvironment(context)
            )
        }
    )

    public static let shell: AgentDefinition = {
        let loginShell = ProcessInfo.processInfo.environment["SHELL"].flatMap { $0.isEmpty ? nil : $0 } ?? "/bin/zsh"
        return AgentDefinition(
            id: "shell",
            displayName: "Shell",
            symbolName: "terminal",
            executableName: (loginShell as NSString).lastPathComponent,
            presetsAgentSessionID: false,
            launch: { context in
                LaunchCommand(executable: loginShell, arguments: ["-l"], environment: hookEnvironment(context))
            },
            resume: nil
        )
    }()
}

/// Claude hook events we subscribe to. PostToolUse and StopFailure are there so a session
/// leaves the attention state once a permission is granted, and leaves the working state
/// when a turn dies on an API error (Stop does not fire then).
let claudeHookEvents = [
    "SessionStart", "UserPromptSubmit", "PreToolUse", "PostToolUse", "PermissionRequest",
    "Notification", "Stop", "StopFailure", "SessionEnd", "SubagentStart", "SubagentStop",
]

func claudeHookSettings(hook: URL) -> String {
    // Claude runs hook commands through a shell, so the path must be quoted.
    let handler: [String: Any] = [
        "type": "command",
        "command": ShellQuoting.quote(hook.path),
        "timeout": 5,
    ]
    var hooks: [String: Any] = [:]
    for event in claudeHookEvents {
        hooks[event] = [["hooks": [handler]]]
    }
    // Claude hands the status line its rate limits, which nothing else exposes. archipel-hook passes
    // them on and then runs the user's own status line, so the terminal looks the same as before.
    let statusLine: [String: Any] = [
        "type": "command",
        "command": ShellQuoting.quote(hook.path) + " statusline",
    ]
    let data = try! JSONSerialization.data(
        withJSONObject: ["hooks": hooks, "statusLine": statusLine],
        options: [.sortedKeys, .withoutEscapingSlashes]
    )
    return String(decoding: data, as: UTF8.self)
}

func codexOverrides(hook: URL) -> [String] {
    [
        // Codex appends the JSON payload as one extra argv element after these.
        "-c", "notify=[\(tomlString(hook.path)), \"codex-notify\"]",
        // Turn completion already arrives through notify. Limiting the terminal
        // notifications to approvals lets the app read every one as "needs approval".
        "-c", "tui.notifications=[\"approval-requested\"]",
        "-c", "tui.notification_method=\"osc9\"",
        "-c", "tui.notification_condition=\"always\"",
    ]
}

func tomlString(_ value: String) -> String {
    var result = "\""
    for scalar in value.unicodeScalars {
        switch scalar {
        case "\"": result += "\\\""
        case "\\": result += "\\\\"
        case "\n": result += "\\n"
        case "\t": result += "\\t"
        case "\r": result += "\\r"
        case _ where scalar.value < 0x20 || scalar.value == 0x7F:
            result += String(format: "\\u%04X", scalar.value)
        default: result.unicodeScalars.append(scalar)
        }
    }
    return result + "\""
}

func hookEnvironment(_ context: LaunchContext) -> [String: String] {
    [
        "ARCHIPEL_SESSION_ID": context.archipelSessionID.uuidString,
        "ARCHIPEL_SOCKET": context.socketURL.path,
    ]
}

extension AgentKind {
    /// The built-in definition for this kind; anything unknown runs as a plain shell.
    public var definition: AgentDefinition {
        .builtIn(id: rawValue) ?? .shell
    }
}
